def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    if not archive:
        raise ValueError("Archive is empty")

    # Select a solution using weighted objective (0.4*value1 + 0.6*value2)
    selected_idx = 0
    max_score = -1
    for i, (sol, obj) in enumerate(archive):
        score = 0.4 * obj[0] + 0.6 * obj[1]
        if score > max_score:
            max_score = score
            selected_idx = i

    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()

    # Calculate current total weight
    current_weight = np.sum(weight_lst * new_solution)

    # Compute marginal contributions for each item (0.7*value1 + 0.3*value2)
    marginal1 = value1_lst / (weight_lst + 1e-6)
    marginal2 = value2_lst / (weight_lst + 1e-6)
    combined_marginal = 0.7 * marginal1 + 0.3 * marginal2

    # Sort items by marginal contribution (descending)
    sorted_indices = np.argsort(-combined_marginal)

    # Hybrid flip strategy: flip up to 3 items with highest marginal contribution
    flip_count = min(3, len(sorted_indices))
    for idx in sorted_indices[:flip_count]:
        if new_solution[idx] == 1:
            # Try to remove if feasible
            if current_weight - weight_lst[idx] <= capacity:
                new_solution[idx] = 0
                current_weight -= weight_lst[idx]
        else:
            # Try to add if feasible
            if current_weight + weight_lst[idx] <= capacity:
                new_solution[idx] = 1
                current_weight += weight_lst[idx]

    # Probabilistic swap of three items to explore diverse neighborhoods
    if len(sorted_indices) >= 3:
        swap_candidates = sorted_indices[:6]  # Consider top 6 items for swap
        if len(swap_candidates) >= 3:
            i, j, k = np.random.choice(swap_candidates, size=3, replace=False)
            # Check if swapping is feasible
            if new_solution[i] != new_solution[j]:
                if new_solution[i] == 1 and current_weight - weight_lst[i] + weight_lst[j] <= capacity:
                    new_solution[i], new_solution[j] = new_solution[j], new_solution[i]
                elif new_solution[j] == 1 and current_weight - weight_lst[j] + weight_lst[i] <= capacity:
                    new_solution[i], new_solution[j] = new_solution[j], new_solution[i]
            if new_solution[j] != new_solution[k]:
                if new_solution[j] == 1 and current_weight - weight_lst[j] + weight_lst[k] <= capacity:
                    new_solution[j], new_solution[k] = new_solution[k], new_solution[j]
                elif new_solution[k] == 1 and current_weight - weight_lst[k] + weight_lst[j] <= capacity:
                    new_solution[j], new_solution[k] = new_solution[k], new_solution[j]

    # 30% chance to remove a random low-marginal item if possible
    if np.random.rand() < 0.3:
        low_marginal_indices = np.where((combined_marginal <= np.percentile(combined_marginal, 30)) & (new_solution == 1))[0]
        if len(low_marginal_indices) > 0:
            random_idx = np.random.choice(low_marginal_indices)
            if current_weight - weight_lst[random_idx] <= capacity:
                new_solution[random_idx] = 0

    return new_solution

