def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    if not archive:
        raise ValueError("Archive is empty")

    # Calculate crowding distance for each solution
    crowding_distances = []
    for i, (sol_i, obj_i) in enumerate(archive):
        distances = []
        for j, (sol_j, obj_j) in enumerate(archive):
            if i != j:
                dist = np.sqrt((obj_j[0] - obj_i[0])**2 + (obj_j[1] - obj_i[1])**2)
                distances.append(dist)
        crowding_distances.append(np.min(distances) if distances else float('inf'))

    # Select solution with minimum crowding distance (most crowded)
    selected_idx = np.argmin(crowding_distances)
    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()
    current_weight = np.sum(weight_lst * new_solution)

    # Calculate combined marginal gains
    marginal_value1 = value1_lst / (weight_lst + 1e-6)
    marginal_value2 = value2_lst / (weight_lst + 1e-6)
    combined_marginal = marginal_value1 + marginal_value2

    # Tier 1: Flip top marginal items for both objectives
    sorted_indices = np.argsort(-combined_marginal)
    flip_count = min(5, len(sorted_indices))
    for idx in sorted_indices[:flip_count]:
        if new_solution[idx] == 1:
            if current_weight - weight_lst[idx] <= capacity:
                new_solution[idx] = 0
                current_weight -= weight_lst[idx]
        else:
            if current_weight + weight_lst[idx] <= capacity:
                new_solution[idx] = 1
                current_weight += weight_lst[idx]

    # Tier 2: Weighted swap mechanism
    if len(sorted_indices) >= 2:
        # Select items with highest and lowest marginal gains
        high_idx = sorted_indices[0]
        low_idx = sorted_indices[-1]

        # Calculate weight difference
        weight_diff = weight_lst[high_idx] - weight_lst[low_idx]

        # Perform swap if feasible
        if new_solution[high_idx] != new_solution[low_idx]:
            if new_solution[high_idx] == 1:
                if current_weight + weight_diff <= capacity:
                    new_solution[high_idx], new_solution[low_idx] = new_solution[low_idx], new_solution[high_idx]
            else:
                if current_weight - weight_diff <= capacity:
                    new_solution[high_idx], new_solution[low_idx] = new_solution[low_idx], new_solution[high_idx]

    # Tier 3: Probabilistic flip based on combined impact
    normalized_scores = combined_marginal / (np.max(combined_marginal) + 1e-6)
    for idx in range(len(normalized_scores)):
        if np.random.rand() < 0.3 * normalized_scores[idx]:
            if new_solution[idx] == 0 and current_weight + weight_lst[idx] <= capacity:
                new_solution[idx] = 1
                current_weight += weight_lst[idx]
            elif new_solution[idx] == 1 and current_weight - weight_lst[idx] <= capacity:
                new_solution[idx] = 0
                current_weight -= weight_lst[idx]

    return new_solution
